#!/usr/bin/env python3
"""Shared evaluation helpers for the batching task."""
import json, sys, pathlib
from cost_model import CostModel, align, HEADS, HIDDEN
from collections import defaultdict

ROOT = pathlib.Path(__file__).resolve().parents[1]

THRESH = {
    1: dict(cost=3.0e11, pad_ratio=0.055, p95_latency_ms=2.1e6, sequential_timecost=2.7e8),
    2: dict(cost=4.8e10, pad_ratio=0.15,  p95_latency_ms=2.1e5, sequential_timecost=3.2e7),
}

def load_requests(bucket):
    path = ROOT / 'input_data' / f'requests_bucket_{bucket}.jsonl'
    reqs = [json.loads(l) for l in open(path)]
    return reqs

def req_map(reqs):
    return {r['request_id']: {'prompt_len': r['prompt_len'], 'gen_len': r['gen_len']} for r in reqs}

def evaluate(requests, plan, bucket):
    cm = CostModel(64)
    m = cm.plan_metrics(requests, plan)
    th = THRESH[bucket]
    ok = True
    res = {}
    for k, v in th.items():
        got = m[k]
        good = got <= v
        ok = ok and good
        res[k] = (got, v, good)
    return m, res, ok

def write_plan(path, plan):
    pathlib.Path(path).parent.mkdir(parents=True, exist_ok=True)
    with open(path, 'w') as f:
        for r in plan:
            f.write(json.dumps(r) + '\n')

def validate(reqs, plan, bucket=None):
    """Schema + constraints check. Returns list of problems."""
    probs = []
    ids = [p['request_id'] for p in plan]
    if len(ids) != len(set(ids)):
        probs.append('duplicate request_ids')
    want = {r['request_id'] for r in reqs}
    if set(ids) != want:
        probs.append(f'id mismatch missing={len(want-set(ids))} extra={len(set(ids)-want)}')
    rm = {r['request_id']: r for r in reqs}
    shapes = set()
    for p in plan:
        sh = p['shape']
        shapes.add((sh['seq_align'], sh['heads_align'], sh['hidden_align']))
        S = sh['seq_align']
        if S % 64 != 0:
            probs.append(f'{p["request_id"]}: seq_align not multiple of 64')
        if S < align(rm[p['request_id']]['prompt_len'], 64):
            probs.append(f'{p["request_id"]}: seq_align too small')
        if sh['heads_align'] != 32 or sh['hidden_align'] != 4096:
            probs.append('bad heads/hidden align')
    if len(shapes) > 8:
        probs.append(f'too many shapes {len(shapes)}')
    by = defaultdict(set)
    for p in plan:
        sh = p['shape']
        by[p['batch_id']].add((sh['seq_align'], sh['heads_align'], sh['hidden_align']))
    for b, s in by.items():
        if len(s) != 1:
            probs.append(f'batch {b} has multiple shapes')
    return probs

def report(name, m, res, ok):
    print(f'--- {name}: {"PASS" if ok else "FAIL"}')
    for k, (got, thr, good) in res.items():
        print(f'   {k:22s} {got:12.4e}  thr {thr:10.3e}  {"ok" if good else "XX"}  ({got/thr*100:5.1f}%)')
