import eval_harness as H
from cost_model import CostModel, align, HEADS, HIDDEN
from collections import defaultdict
import json
cm=CostModel(64)

def shape_of(S): return {'seq_align':S,'heads_align':32,'hidden_align':4096}

def plan_from_batches(batches, req_by_id, shape_val=None):
    plan=[]
    for bi,members in enumerate(batches):
        bid=f"b-{bi:04d}"
        Smax=max(req_by_id[m]['S'] for m in members)
        sh=shape_of(shape_val if shape_val is not None else Smax)
        for m in members:
            plan.append({'request_id':m,'batch_id':bid,'shape':sh})
    return plan

def build_group_exactG(reqs, K=10000, sband=None):
    rg=defaultdict(list)
    for r in reqs: rg[r['gen_len']].append(r)
    batches=[]
