            batches.append([r['request_id'] for r in rs])
        else:
            cur=[]
            for r in rs:
                if cur and (r['S']-cur[0]['S']>sband or len(cur)>=K):
                    batches.append([x['request_id'] for x in cur]); cur=[]
                cur.append(r)
            if cur: batches.append([x['request_id'] for x in cur])
    return batches

